"""Bilingual TikZ views of the same epistemic model used by the offline HTML."""
from pathlib import Path
import json
R=Path(__file__).resolve().parents[1]
def main():
 g=json.loads((R/'ui/epistemic/graph.json').read_text());nodes={n['id']:n for n in g['nodes']}
 c=json.loads((R/'research/revision_v17/results/cassini.json').read_text())
 score=c['sum_log_score_difference']
 for lang in ['es','en']:
  def T(es,en):return es if lang=='es' else en
  def b(v):return v[lang].replace('&',r'\&')
  out=R/'figures'/lang;out.mkdir(exist_ok=True)
  lines=[r'\begin{tikzpicture}[x=1cm,y=1cm,>=Latex,font=\small,text=navy]',r'\path[use as bounding box] (-.1,.6) rectangle (16.4,-20.35);',r'\node[anchor=center,font=\bfseries\small,text=violet] at (8.1,.3) {'+T('Mapa epistémico · Cómo se sostiene cada resultado','Epistemic map · How each result is supported')+'};',r'\node[draw=navy!35,fill=navy!3,rounded corners=3pt,text width=15.8cm,align=center,inner sep=8pt] at (8.1,-.7) {\textbf{'+T('Premisa física y operador de observación','Physical premise and observation operator')+r'}\\[3pt]'+T('Plantilla efectiva explícita; calibración de masa; excentricidad; predicciones propias de cada teoría.','Explicit effective template; mass calibration; eccentricity; theory-specific predictions.')+'};']
  for j,t in enumerate([T('Resultado','Result'),T('Cálculo y evidencia','Computation and evidence'),T('Aplicación y condiciones','Application and conditions')]):
   lines.append(r'\node[anchor=west,font=\bfseries\footnotesize,text=violet] at ('+str(j*5.55)+',-1.85) {'+t+'};')
  rows=[('gp',r'$Db=Db^{\prime}$; $DKD^T=DK^{\prime}D^T$',T('La ley posterior se determina por sus contrastes.','Contrasts determine the posterior law.'),r'$D_{\rm KL}=1.402585$ nats',T('Control sintético de covarianza; soportes singulares explícitos.','Synthetic covariance control; singular supports explicit.'),T('Criterio en malla finita; estabilidad posterior y conectividad FractalGo.','Finite-grid criterion; posterior stability and FractalGo connectivity.')),
  ('cassini',r'$y=A s+X\beta+\epsilon$',T('1696 épocas reconstruidas; cuatro covarianzas temporales.','1696 reconstructed epochs; four temporal covariances.'),T('Pasada 12: $0/1024$ excedencias','Pass 12: $0/1024$ exceedances'),T('Discrepancia temporal localizada por pasada.','Temporal discrepancy localized by pass.'),T(r'Mezcla exploratoria sobre datos reconstruidos; amplitud óptica distinta de $(\alpha,\lambda)$.',r'Exploratory mixture on reconstructed data; optical amplitude distinct from $(\alpha,\lambda)$ posterior.')),
  ('information',r'$K_{\pi,L}=1-R_{\pi,L}(E)/R_{\pi,L}(\varnothing)$',T('Retención relativa a un objeto, prior y pérdida declarados.','Retention relative to a declared target, prior and loss.'),r'$J_{\rm mix}=0.345509<0.555556$',T('Fisher y riesgo resuelven el control de mezcla.','Fisher and risk resolve the mixture control.'),T('Objetivo, prior y pérdida declarados; riesgo basal positivo y finito.','Declared target, prior and loss; positive finite baseline risk.')),
  ('dcae',r'$I_j^\uparrow=[1-\mathcal R_j]_+$',T(r'v0.6: componente, protocolo y $\Delta_j$ firmado.',r'v0.6: component, protocol and signed $\Delta_j$.'),r'$\Delta_{\rm soporte}=-0.0092143$' if lang=='es' else r'$\Delta_{\rm support}=-0.0092143$',T('COSMOS: el orden cambia con tolerancia y observable.','COSMOS: ordering changes with tolerance and observable.'),T('Descriptor de soporte en tablas; medición física DCAE pendiente.','Table-based support descriptor; physical DCAE measurement pending.'))]
  rows.insert(0,('physics',r'$a_r=-\mu[1+\alpha(1+x)e^{-x}]/r^2$',T('Gradiente, calibración de masa y excentricidad finita.','Gradient, mass calibration and finite eccentricity.'),T('Bessel, cuadratura e integración','Bessel, quadrature and integration'),T('Error semilatus: ','Semilatus error: ')+f"${100*nodes['physical_result']['metrics']['semilatus_error_e_0.82697_x_1']:.2f}\\%$"+r' ($e=0.82697$, $x=1$).',T('Plantilla fenomenológica; propagación luminosa con hipótesis métricas explícitas.','Phenomenological template; light propagation with explicit metric assumptions.')))
  rows.insert(4,('cases',r'$C_{\rm shared};\ Q_2$',T('Covarianza Gaia por tránsito; respuesta QUMOND al campo externo.','Gaia transit covariance; QUMOND external-field response.'),f"$Q_2={nodes['cases_result']['metrics']['Q2_s_minus2']/1e-26:.5f}\\times10^{{-26}}$ "+r'$\mathrm{s}^{-2}$',T('Registros ESA y cuadratura del modelo de campo externo.','ESA records and quadrature of the external-field model.'),T('Gaia a diseño fijo; cuadrupolo teórico con campo e interpolación declarados.','Gaia at fixed design; theoretical quadrupole with declared field and interpolation.')))
  for row,(r,f,desc,metric,check,limit) in enumerate(rows):
   y=-3.65-row*2.65;color=['navy','violet','plum','cyan','navy','violet'][row]
   titles=[T('Gaia y QUMOND','Gaia and QUMOND') if r=='cases' else b(g['routes'][r]),b(nodes[{'physics':'physical_check'}.get(r,r+'_check')]['title']),{'physics':T('Calibrar la respuesta','Calibrate the response'),'gp':T('Auditar emuladores','Audit emulators'),'cassini':T('Evaluar el modelo temporal','Assess the temporal model'),'information':T('Comparar transformaciones','Compare transformations'),'cases':T('Relacionar geometría y física','Connect geometry and physics'),'dcae':T('Describir el acceso','Describe access')}[r]]
   bodies=[f+r'\\[5pt]'+desc,metric+r'\\[5pt]'+check,limit]
   for j in range(3):
    lines.append(r'\node[draw='+color+r'!55,fill='+color+r'!3,rounded corners=3pt,text width=4.65cm,minimum height=1.95cm,align=left,inner sep=7pt'+''+'] ('+r+str(j)+') at ('+str(2.45+j*5.55)+','+str(y)+r') {\textbf{'+titles[j]+r'}\\[6pt]'+bodies[j]+'};')
   for j in range(2):lines.append(r'\draw[->,'+color+r'!60,thick] ('+r+str(j)+'.east)--('+r+str(j+1)+'.west);')
  lines+=[r'\node[draw=violet!40,fill=violet!5,rounded corners=2pt,text width=15.8cm,align=center,inner sep=7pt] at (8.1,-19.15) {\textbf{'+T('Identificabilidad + ley conjunta + adecuación predictiva','Identifiability + joint law + predictive adequacy')+r'}\\[4pt]'+T('GRAVITAS + FractalGo: reproducir los cálculos, inspeccionar la evidencia y extender los contrastes.','GRAVITAS + FractalGo: reproduce calculations, inspect evidence and extend the tests.')+'};',r'\node[anchor=west,font=\tiny,text=navy!65] at (0,-20.15) {'+T('Mismo modelo de contenidos que el grafo interactivo. SHA-256: ','Same content model as the interactive graph. SHA-256: ')+g['content_sha256'][:16]+'.};',r'\end{tikzpicture}']
  (out/'epistemic_graph.tex').write_text('\n'.join(lines)+'\n')
  lines=[r'\begin{tikzpicture}[x=1cm,y=1cm,>=Latex,font=\small,text=navy]',r'\path[use as bounding box] (-.1,.6) rectangle (16.4,-7.9);',r'\node[anchor=center,font=\bfseries\small,text=violet] at (8.1,.3) {'+T('Relatividad general · De la observación a la inferencia','General relativity · From observation to inference')+'};',r'\node[anchor=center,align=center,font=\large\bfseries,text width=16cm] at (8.1,-.6) {'+T('Conservar la información que decide el contraste físico.','Preserve the information that determines the physical test.')+'};']
  chain=[T('Modelo físico','Physical model'),T('Operador de medida','Measurement operator'),T('Ley conjunta','Joint law'),T('Predicción comprobable','Testable prediction')]
  for j,title in enumerate(chain):
   lines.append(r'\node[draw=navy!30,fill=navy!3,rounded corners=2pt,text width=3.5cm,minimum height=.8cm,align=center,inner sep=5pt] (c'+str(j)+') at ('+str(1.9+j*4.15)+r',-1.7) {\textbf{'+title+'}};')
   if j:lines.append(r'\draw[->,navy!60,thick] (c'+str(j-1)+'.east)--(c'+str(j)+'.west);')
  panels=[('violet',T('Criterio exacto','Exact criterion'),r'$Db,\ DKD^T$',T('Determinar la ley posterior\na través de sus contrastes.','Determine the posterior law\nthrough its contrasts.')),
   ('cyan',T('Información','Information'),r'$K_{\pi,L}=1-R(E)/R(\varnothing)$',T('Cuantificar la reducción\nde riesgo para una decisión.','Quantify risk reduction\nfor a target and a decision.')),
   ('plum',T('Predicción local','Local prediction'),T('Log-score: ','Log score: ')+f'$+{score:.5f}$',T('Cassini: mejora por bloques;\npasada 12 por resolver.','Cassini: blocked improvement;\npass 12 remains unresolved.'))]
  for j,(color,title,formula,body) in enumerate(panels):
   x=2.5+j*5.6
   lines.append(r'\node[draw='+color+r'!55,fill='+color+r'!4,rounded corners=4pt,text width=4.55cm,minimum height=2.65cm,align=center,inner sep=8pt] at ('+str(x)+r',-4.05) {\textcolor{'+color+r'}{\bfseries '+title+r'}\\[12pt]'+formula+r'\\[12pt]'+body.replace('\n',r'\\')+'};')
  lines += [r'\node[draw=violet!35,fill=white,rounded corners=3pt,align=center,text width=15.7cm,inner sep=10pt] at (8.1,-6.45) {\textbf{'+T(r'De la respuesta física a una inferencia auditable',r'From the physical response to an auditable inference')+r'}\\[6pt]'+T('GRAVITAS + FractalGo: cálculos, diagnósticos y procedencia reproducibles.','GRAVITAS + FractalGo: reproducible calculations, diagnostics and provenance.')+'};',r'\node[anchor=west,font=\footnotesize,text=navy!70] at (0,-7.5) {'+T('GP: malla finita. Información: riesgo declarado. Cassini: reconstrucción y mezcla exploratoria.','GP: finite grid. Information: declared risk. Cassini: reconstruction and exploratory mixture.')+'};',r'\end{tikzpicture}']
  (out/'visual_abstract.tex').write_text('\n'.join(lines)+'\n')
 print('TikZ ES/EN generated from epistemic model / generado desde el modelo epistémico')
if __name__=='__main__':main()
